<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRouter} from 'vue-router'
import {Server,CheckCircle2,TriangleAlert,WifiOff,RefreshCw,Plus,Search,ArrowUpRight,Boxes,Activity} from 'lucide-vue-next'
import {useMonitor} from '../stores/monitor'
import {relative,percent} from '../services/format'
import ServerTable from '../components/ServerTable.vue'
import ServerEditor from '../components/ServerEditor.vue'
import StatusBadge from '../components/StatusBadge.vue'
const store=useMonitor(),router=useRouter(),search=ref(''),adding=ref(false)
const servers=computed(()=>store.data?.servers||[])
const filtered=computed(()=>servers.value.filter(s=>`${s.name} ${s.hostname}`.toLowerCase().includes(search.value.toLowerCase())))
const healthy=computed(()=>servers.value.filter(s=>s.health_state==='Healthy'&&!['Unreachable','Endpoint unreachable'].includes(s.availability)).length)
const unreachable=computed(()=>servers.value.filter(s=>['Unreachable','Endpoint unreachable'].includes(s.availability)).length)
const attention=computed(()=>servers.value.length-healthy.value-unreachable.value)
const stats=computed(()=>[{label:'Servers monitored',value:servers.value.length,icon:Server,tone:'blue'},{label:'Healthy',value:healthy.value,icon:CheckCircle2,tone:'good'},{label:'Needs attention',value:attention.value,icon:TriangleAlert,tone:'warn'},{label:'Unreachable',value:unreachable.value,icon:WifiOff,tone:'bad'}])
</script>
<template><div class="page-header"><div><h1>Overview</h1><div class="subtitle">Your infrastructure, at a glance. <span v-if="store.data?.demo" class="demo-badge">Demo data</span></div></div><div class="header-actions"><q-btn outline no-caps :loading="store.loading" @click="store.refresh"><RefreshCw :size="16"/>Refresh</q-btn><q-btn v-if="store.user?.is_admin" color="primary" unelevated no-caps @click="adding=true"><Plus :size="18"/>Add server</q-btn></div></div>
<div v-if="store.loading&&!store.data" class="empty"><q-spinner color="primary"/>Loading infrastructure…</div>
<template v-else><div class="stats-grid"><div v-for="stat in stats" :key="stat.label" class="stat-panel"><div class="stat-icon" :class="stat.tone"><component :is="stat.icon" :size="24"/></div><div><b>{{stat.value}}</b><span>{{stat.label}}</span></div></div></div>
<div class="dashboard-grid"><section class="panel servers-panel"><header class="panel-header"><h2>Servers</h2><div class="panel-tools"><span class="muted count-label">{{servers.length}} servers</span><label class="search-box"><Search :size="16"/><input v-model="search" placeholder="Search servers…" aria-label="Search servers"/></label></div></header><ServerTable :servers="filtered" @select="s=>router.push(`/servers?server=${s.id}`)"/></section>
<section class="panel incidents-panel"><header class="panel-header"><h2>Active incidents <span class="count-pill">{{store.data?.incidents.length||0}}</span></h2><router-link to="/alerts">View all</router-link></header><div class="incident-previews"><button v-for="i in store.data?.incidents.slice(0,3)" :key="i.id" class="incident-preview" :class="i.severity" @click="router.push(`/alerts?incident=${i.id}`)"><TriangleAlert :size="22"/><div><div class="incident-line"><strong>{{i.rule==='low_health'?'Low server health':i.rule==='unreachable'?'Server unreachable':i.title}}</strong><small>{{relative(i.opened_at)}}</small></div><span>{{i.server_name}}</span><p>{{i.rule==='low_health'?`Health is ${percent(i.evidence.score as number)}. Investigate resource usage.`:i.rule==='unreachable'?'Unable to reach the server from the monitoring worker.':i.title}}</p><span class="severity-label">{{i.severity}}</span><span class="target-label">{{i.application?'Application':'Server'}}</span></div></button><div v-if="!store.data?.incidents.length" class="empty compact"><CheckCircle2 :size="32" class="text-positive"/><b>All clear</b><span>No active incidents.</span></div></div></section>
<section class="panel applications-panel"><header class="panel-header"><h2>Applications</h2><router-link to="/applications">{{store.data?.applications.length||0}} applications <ArrowUpRight :size="14"/></router-link></header><div class="application-table"><div class="table-head app-grid"><span>Application</span><span>Health</span><span>Response time</span><span>Last check</span></div><button v-for="a in store.data?.applications.slice(0,5)" :key="a.id" class="application-row app-grid" @click="router.push(`/applications?app=${a.id}`)"><div class="identity"><Boxes :size="22"/><div><strong>{{a.name}}</strong><small>{{a.url.replace(/^https?:\/\//,'')}}</small></div></div><StatusBadge :status="a.effective_state"/><span :class="a.latency_ms&&a.latency_ms>a.latency_threshold?'danger-text':''">{{a.latency_ms!==null?Math.round(a.latency_ms)+' ms':a.last_error?'Timeout':'—'}}</span><small class="muted">{{relative(a.last_checked)}}</small></button><div v-if="!store.data?.applications.length" class="empty compact">No applications configured yet.</div></div></section>
<section class="panel activity-panel"><header class="panel-header"><h2>Activity</h2><span class="muted">Latest checks</span></header><div class="activity-list"><div v-for="s in [...servers].sort((a,b)=>(b.last_seen||'').localeCompare(a.last_seen||'')).slice(0,6)" :key="s.id" class="activity-row"><i :class="s.fresh&&s.health_state==='Healthy'?'good':'bad'"/><div><b>{{s.name}}</b><span>{{s.fresh?`Agent report · ${percent(s.last_score)} health`:'Awaiting fresh telemetry'}}</span></div><small>{{relative(s.last_seen)}}</small></div><div v-if="!servers.length" class="empty compact"><Activity :size="28"/>Waiting for the first agent report.</div></div></section></div></template><ServerEditor v-model="adding"/>
</template>
